mapper.insert:
INSERT INTO notice (
    id, title, content, is_planned, is_important, created_at, updated_at, is_deleted
) VALUES (
    #{id}, #{title}, #{content}, #{isPlanned}, #{isImportant}, NOW(), NOW(), 0
)

mapper.select:
SELECT id, fd_filepath_img, num, save_name, file_size, file_path AS filePath
FROM notice_file
WHERE num = #{num}
